<script>
const editCustomerEventRows=document.getElementById('editCustomerEventRows');
function refreshEditCustomerEvents(){const rows=[...editCustomerEventRows.querySelectorAll('.edit-customer-event-row')];rows.forEach((row,index)=>{row.querySelector('.edit-event-number').textContent=(index+1)+'.';row.querySelector('[data-event-name]').name=`customer_events[${index}][name]`;row.querySelector('[data-event-date]').name=`customer_events[${index}][date]`;row.querySelector('[data-event-tba]').name=`customer_events[${index}][tba]`;row.querySelector('.edit-event-remove').disabled=rows.length===1})}
function bindEditCustomerEvent(row){const tba=row.querySelector('[data-event-tba]'),date=row.querySelector('[data-event-date]');tba.addEventListener('change',()=>{date.disabled=tba.checked;if(tba.checked)date.value=''});row.querySelector('.edit-event-remove').addEventListener('click',()=>{if(editCustomerEventRows.children.length<=1)return;row.remove();refreshEditCustomerEvents()})}
[...editCustomerEventRows.querySelectorAll('.edit-customer-event-row')].forEach(bindEditCustomerEvent);
document.getElementById('editAddCustomerEvent').addEventListener('click',()=>{const row=document.createElement('div');row.className='edit-customer-event-row';row.innerHTML='<span class="edit-event-number"></span><div class="edit-field"><label>Nama Event *</label><input data-event-name placeholder="Contoh: DP, PP, MPP, PILOT, SOP" required></div><div class="edit-field"><label>Tanggal / Periode</label><input data-event-date type="text" maxlength="50" placeholder="Contoh: 2027-10-15 atau Q4 2027"></div><label class="edit-event-tba"><input data-event-tba type="checkbox" value="1"> TBA</label><button class="edit-event-remove" type="button" aria-label="Hapus event">&times;</button>';editCustomerEventRows.appendChild(row);bindEditCustomerEvent(row);refreshEditCustomerEvents();row.querySelector('[data-event-name]').focus()});
refreshEditCustomerEvents();
function a00EditQuantityRaw(value){const normalized=String(value??'').replace(/\.0+$/,'').replace(/[^0-9]/g,'');return normalized===''?'':String(Number(normalized))}function a00EditQuantityDisplay(value){const raw=a00EditQuantityRaw(value);return raw===''?'':new Intl.NumberFormat('id-ID').format(Number(raw))}function formatA00EditQuantity(input){const raw=a00EditQuantityRaw(input.value);input.value=a00EditQuantityDisplay(raw);input.closest('[data-forecast-row]')?.querySelector('[data-qty-raw]')?.setAttribute('value',raw);const hidden=input.closest('[data-forecast-row]')?.querySelector('[data-qty-raw]');if(hidden)hidden.value=raw}
function renderA00EditForecast(card,seed=[]){const index=card.dataset.itemIndex,life=card.querySelector(`[name="items[${index}][product_life_years]"]`),years=Math.max(0,Math.min(99,Number(life.value)||0)),type=card.querySelector('[data-forecast-type]').value,startYear=Number(card.querySelector('[data-forecast-start]').value)||0,container=card.querySelector('[data-forecast-rows]'),previous=new Map(seed.map(row=>[`${row.year_number}-${row.month_number||0}`,a00EditQuantityRaw(row.quantity)]));if(!seed.length)container.querySelectorAll('[data-forecast-row]').forEach(row=>previous.set(`${row.querySelector('[data-year]').value}-${row.querySelector('[data-month]')?.value||0}`,row.querySelector('[data-qty-raw]').value));container.innerHTML='';let rowIndex=0;for(let year=1;year<=years;year++){for(let month=1;month<=(type==='month'?12:1);month++){const row=document.createElement('div'),key=`${year}-${type==='month'?month:0}`,calendarYear=startYear?startYear+year-1:0,raw=previous.get(key)??'';row.className='a00-edit-forecast-row';row.dataset.forecastRow='';row.innerHTML=`<span>${type==='month'?`${calendarYear||'-'} · Bulan ${month}`:`${calendarYear||'-'}`}</span><input type="hidden" data-year name="items[${index}][quantity_forecasts][${rowIndex}][year_number]" value="${year}"><input type="hidden" data-calendar-year name="items[${index}][quantity_forecasts][${rowIndex}][calendar_year]" value="${calendarYear}">${type==='month'?`<input type="hidden" data-month name="items[${index}][quantity_forecasts][${rowIndex}][month_number]" value="${month}">`:''}<input type="text" inputmode="numeric" data-qty value="${a00EditQuantityDisplay(raw)}" placeholder="Quantity"><input type="hidden" data-qty-raw name="items[${index}][quantity_forecasts][${rowIndex}][quantity]" value="${raw}"><span class="a00-edit-forecast-muted">${type==='year'?'rata-rata ÷ 12':''}</span>`;container.appendChild(row);rowIndex++}}card.querySelector('[data-forecast-note]').textContent=years?`${years} tahun · ${rowIndex} periode`:'Isi Product Life terlebih dahulu';updateA00EditForecast(card)}
function updateA00EditForecast(card){const index=card.dataset.itemIndex,values=[...card.querySelectorAll('[data-qty-raw]')].map(input=>Number(input.value)||0),total=values.reduce((sum,value)=>sum+value,0),type=card.querySelector('[data-forecast-type]').value,years=Number(card.querySelector(`[name="items[${index}][product_life_years]"]`).value)||0,uom=card.querySelector(`[name="items[${index}][quantity_uom]"]`).value,average=type==='month'?(values.length?total/values.length:0):(years?total/years:0);card.querySelector('[data-forecast-total]').textContent=`${new Intl.NumberFormat('id-ID').format(total)} ${uom}`;card.querySelector(`[name="items[${index}][quantity]"]`).value=Math.round(average);card.querySelector(`[name="items[${index}][quantity_basis]"]`).value=type==='month'?'per Month':'per Year'}
document.querySelectorAll('[data-a00-edit-item]').forEach(card=>{const panel=card.querySelector('[data-forecast-panel]'),toggle=card.querySelector('[data-forecast-toggle]'),enabled=card.querySelector('[data-forecast-enabled]'),seed=JSON.parse(card.querySelector('[data-forecast-seed]').textContent||'[]');card.querySelector('[data-forecast-start]').value=seed[0]?.calendar_year||new Date().getFullYear();const setEnabled=value=>{enabled.value=value?'1':'0';panel.hidden=!value;toggle.textContent=value?'Gunakan quantity biasa':'+ Quantity berbeda tiap periode';if(value)renderA00EditForecast(card,seed)};toggle.addEventListener('click',()=>setEnabled(panel.hidden));card.querySelector('[data-forecast-type]').addEventListener('change',()=>renderA00EditForecast(card));card.querySelector('[data-forecast-start]').addEventListener('input',()=>renderA00EditForecast(card));const index=card.dataset.itemIndex;card.querySelector(`[name="items[${index}][product_life_years]"]`).addEventListener('input',()=>{if(!panel.hidden)renderA00EditForecast(card)});card.querySelector('[data-forecast-rows]').addEventListener('input',event=>{if(event.target.matches('[data-qty]'))formatA00EditQuantity(event.target);updateA00EditForecast(card)});if(!panel.hidden)renderA00EditForecast(card,seed)});
</script>
@endsection
